CREATE TABLE "Worksite" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "name" TEXT NOT NULL, "code" TEXT, "description" TEXT, "address" TEXT, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Worksite_pkey" PRIMARY KEY ("id"), CONSTRAINT "Worksite_companyId_name_key" UNIQUE ("companyId", "name"));
CREATE TABLE "Schedule" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "name" TEXT NOT NULL, "weeklyMinutes" INTEGER, "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "Schedule_pkey" PRIMARY KEY ("id"), CONSTRAINT "Schedule_companyId_name_key" UNIQUE ("companyId", "name"));
CREATE TABLE "ScheduleDay" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "scheduleId" UUID NOT NULL, "dayOfWeek" INTEGER NOT NULL CHECK ("dayOfWeek" BETWEEN 0 AND 6), "expectedMinutes" INTEGER NOT NULL CHECK ("expectedMinutes" >= 0 AND "expectedMinutes" <= 1440), "defaultStartTime" TEXT, "defaultEndTime" TEXT, "defaultBreakMinutes" INTEGER CHECK ("defaultBreakMinutes" >= 0), CONSTRAINT "ScheduleDay_pkey" PRIMARY KEY ("id"), CONSTRAINT "ScheduleDay_scheduleId_dayOfWeek_key" UNIQUE ("scheduleId", "dayOfWeek"));
CREATE TABLE "UserScheduleAssignment" ("id" UUID NOT NULL, "companyId" UUID NOT NULL, "userId" UUID NOT NULL, "scheduleId" UUID NOT NULL, "validFrom" DATE NOT NULL, "validUntil" DATE, "createdAt" TIMESTAMPTZ(6) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "UserScheduleAssignment_pkey" PRIMARY KEY ("id"), CONSTRAINT "UserScheduleAssignment_valid_dates" CHECK ("validUntil" IS NULL OR "validUntil" >= "validFrom"));
CREATE INDEX "Worksite_companyId_idx" ON "Worksite"("companyId"); CREATE INDEX "Schedule_companyId_idx" ON "Schedule"("companyId"); CREATE INDEX "ScheduleDay_companyId_idx" ON "ScheduleDay"("companyId"); CREATE INDEX "UserScheduleAssignment_companyId_userId_validFrom_idx" ON "UserScheduleAssignment"("companyId", "userId", "validFrom");
ALTER TABLE "Worksite" ADD CONSTRAINT "Worksite_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "Schedule" ADD CONSTRAINT "Schedule_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "ScheduleDay" ADD CONSTRAINT "ScheduleDay_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "ScheduleDay" ADD CONSTRAINT "ScheduleDay_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "Schedule"("id") ON DELETE CASCADE; ALTER TABLE "UserScheduleAssignment" ADD CONSTRAINT "UserScheduleAssignment_companyId_fkey" FOREIGN KEY ("companyId") REFERENCES "Company"("id") ON DELETE CASCADE; ALTER TABLE "UserScheduleAssignment" ADD CONSTRAINT "UserScheduleAssignment_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE; ALTER TABLE "UserScheduleAssignment" ADD CONSTRAINT "UserScheduleAssignment_scheduleId_fkey" FOREIGN KEY ("scheduleId") REFERENCES "Schedule"("id") ON DELETE CASCADE;
ALTER TABLE "Worksite" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Worksite" FORCE ROW LEVEL SECURITY; ALTER TABLE "Schedule" ENABLE ROW LEVEL SECURITY; ALTER TABLE "Schedule" FORCE ROW LEVEL SECURITY; ALTER TABLE "ScheduleDay" ENABLE ROW LEVEL SECURITY; ALTER TABLE "ScheduleDay" FORCE ROW LEVEL SECURITY; ALTER TABLE "UserScheduleAssignment" ENABLE ROW LEVEL SECURITY; ALTER TABLE "UserScheduleAssignment" FORCE ROW LEVEL SECURITY;
CREATE POLICY "worksite_tenant" ON "Worksite" FOR ALL USING ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid); CREATE POLICY "schedule_tenant" ON "Schedule" FOR ALL USING ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid); CREATE POLICY "schedule_day_tenant" ON "ScheduleDay" FOR ALL USING ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid); CREATE POLICY "schedule_assignment_tenant" ON "UserScheduleAssignment" FOR ALL USING ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid) WITH CHECK ("companyId" = NULLIF(current_setting('app.company_id',true),'')::uuid);
CREATE FUNCTION "enforce_schedule_relation_company"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE parent_company UUID; BEGIN SELECT "companyId" INTO parent_company FROM public."Schedule" WHERE "id"=NEW."scheduleId"; IF parent_company IS NULL OR parent_company<>NEW."companyId" THEN RAISE EXCEPTION 'CROSS_TENANT_SCHEDULE'; END IF; IF TG_TABLE_NAME='UserScheduleAssignment' AND NOT EXISTS(SELECT 1 FROM public."User" WHERE "id"=NEW."userId" AND "companyId"=NEW."companyId") THEN RAISE EXCEPTION 'CROSS_TENANT_USER_SCHEDULE'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER "ScheduleDay_company_consistency" BEFORE INSERT OR UPDATE ON "ScheduleDay" FOR EACH ROW EXECUTE FUNCTION "enforce_schedule_relation_company"(); CREATE TRIGGER "UserScheduleAssignment_company_consistency" BEFORE INSERT OR UPDATE ON "UserScheduleAssignment" FOR EACH ROW EXECUTE FUNCTION "enforce_schedule_relation_company"();DROP TRIGGER "ScheduleDay_company_consistency" ON "ScheduleDay"; DROP TRIGGER "UserScheduleAssignment_company_consistency" ON "UserScheduleAssignment"; DROP FUNCTION "enforce_schedule_relation_company"();
CREATE FUNCTION "enforce_schedule_day_company"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE parent_company UUID; BEGIN SELECT "companyId" INTO parent_company FROM public."Schedule" WHERE "id"=NEW."scheduleId"; IF parent_company IS NULL OR parent_company<>NEW."companyId" THEN RAISE EXCEPTION 'CROSS_TENANT_SCHEDULE'; END IF; RETURN NEW; END; $$;
CREATE FUNCTION "enforce_schedule_assignment_company"() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,public AS $$ DECLARE schedule_company UUID; user_company UUID; BEGIN SELECT "companyId" INTO schedule_company FROM public."Schedule" WHERE "id"=NEW."scheduleId"; SELECT "companyId" INTO user_company FROM public."User" WHERE "id"=NEW."userId"; IF schedule_company IS NULL OR user_company IS NULL OR schedule_company<>NEW."companyId" OR user_company<>NEW."companyId" THEN RAISE EXCEPTION 'CROSS_TENANT_USER_SCHEDULE'; END IF; RETURN NEW; END; $$;
CREATE TRIGGER "ScheduleDay_company_consistency" BEFORE INSERT OR UPDATE ON "ScheduleDay" FOR EACH ROW EXECUTE FUNCTION "enforce_schedule_day_company"(); CREATE TRIGGER "UserScheduleAssignment_company_consistency" BEFORE INSERT OR UPDATE ON "UserScheduleAssignment" FOR EACH ROW EXECUTE FUNCTION "enforce_schedule_assignment_company"();